WHERE e.tenant_id = #{tenantId}
  AND e.del_flag = '0'

  AND e.application_id = #{query.applicationId}


  AND e.object_id = #{query.objectId}


  AND e.entry_id = #{query.entryId}


  AND (e.extension_code LIKE CONCAT('%', #{query.keyword}, '%')
    OR e.extension_name LIKE CONCAT('%', #{query.keyword}, '%'))


  AND e.extension_type = #{query.extensionType}


  AND e.hook_code = #{query.hookCode}


  AND e.status = #{query.status}

