WHERE e.tenant_id = #{tenantId}
  AND e.id = #{id}
  AND e.del_flag = '0'
LIMIT 1

SELECT 
FROM ai_business_extension
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND del_flag = '0'
LIMIT 1

SELECT COUNT(1)
FROM ai_business_extension
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}
  AND extension_code = #{extensionCode}
  AND del_flag = '0'

  AND id != #{excludeId}

SELECT COUNT(1)
FROM ai_business_application_object ao
INNER JOIN ai_business_object o
  ON o.tenant_id = ao.tenant_id
 AND o.id = ao.object_id
 AND o.del_flag = '0'
WHERE ao.tenant_id = #{tenantId}
  AND ao.application_id = #{applicationId}
  AND ao.object_id = #{objectId}
  AND ao.del_flag = '0'

SELECT COUNT(1)
FROM ai_business_app
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}
  AND id = #{entryId}
  AND del_flag = '0'

mapper.update:
UPDATE ai_business_extension
SET lock_user_id = #{userId},
    lock_username = #{username},
    lock_token_hash = #{lockToken},
    lock_time = #{now},
    lock_expire_time = #{expireTime}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND del_flag = '0'
  AND (lock_user_id IS NULL OR lock_expire_time <= #{now})

UPDATE ai_business_extension
SET lock_time = #{now},
    lock_expire_time = #{expireTime}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND del_flag = '0'
  AND lock_user_id = #{userId}
  AND lock_token_hash = #{lockToken}
  AND lock_expire_time > #{now}

UPDATE ai_business_extension
SET lock_user_id = NULL,
    lock_username = NULL,
    lock_token_hash = NULL,
    lock_time = NULL,
    lock_expire_time = NULL
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND del_flag = '0'
  AND lock_user_id = #{userId}
  AND lock_token_hash = #{lockToken}

